-- mistri store layout: command-events, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_command_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_command_receipt" (
  id TEXT COLLATE BINARY PRIMARY KEY NOT NULL,
  app_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  realm TEXT COLLATE BINARY NOT NULL CHECK (realm IN ('tenant', 'platform')),
  tenant_id TEXT COLLATE BINARY NOT NULL,
  actor_id TEXT COLLATE BINARY NOT NULL,
  command_id TEXT COLLATE BINARY NOT NULL,
  command_version INTEGER NOT NULL CHECK (command_version > 0),
  idempotency_key TEXT COLLATE BINARY NOT NULL,
  fingerprint TEXT NOT NULL,
  result_json TEXT NOT NULL CHECK (json_valid(result_json) AND length(CAST(result_json AS BLOB)) <= 16384),
  request_id TEXT NOT NULL,
  completed_at TEXT NOT NULL,
  membership_id TEXT COLLATE BINARY NOT NULL,
  membership_version TEXT COLLATE BINARY NOT NULL,
  realm_version TEXT COLLATE BINARY NOT NULL,
  roles_json TEXT NOT NULL CHECK (json_valid(roles_json) AND length(CAST(roles_json AS BLOB)) <= 65536),
  deployment TEXT COLLATE BINARY NOT NULL,
  target TEXT NOT NULL,
  owners_json TEXT NOT NULL CHECK (json_valid(owners_json) AND json_type(owners_json) = 'array' AND length(CAST(owners_json AS BLOB)) <= 65536),
  keys_json TEXT NOT NULL CHECK (json_valid(keys_json) AND json_type(keys_json) = 'array' AND length(CAST(keys_json AS BLOB)) <= 2097152),
  changes_json TEXT NOT NULL CHECK (json_valid(changes_json) AND json_type(changes_json) = 'array' AND length(CAST(changes_json AS BLOB)) <= 4194304),
  manifest_json TEXT CHECK (manifest_json IS NULL OR (typeof(manifest_json) = 'text' AND json_valid(manifest_json) AND json_type(manifest_json) = 'array' AND length(CAST(manifest_json AS BLOB)) BETWEEN 1 AND 65536)),
  event_count INTEGER CHECK (event_count IS NULL OR (typeof(event_count) = 'integer' AND event_count BETWEEN 1 AND 32)),
  digest TEXT CHECK (digest IS NULL OR (typeof(digest) = 'text' AND length(digest) = 64 AND digest NOT GLOB '*[^0-9a-f]*')),
  CHECK (realm = 'tenant' OR tenant_id = ''),
  CHECK ((manifest_json IS NULL) = (event_count IS NULL) AND (manifest_json IS NULL) = (digest IS NULL)),
  UNIQUE (app_id, store_id, source_id, realm, tenant_id, actor_id, command_id, command_version, idempotency_key)
);
CREATE INDEX "__mistri_command_receipt_completed" ON "__mistri_command_receipt" (completed_at);
CREATE TABLE "__mistri_sequence_number" (
  app_id TEXT COLLATE BINARY NOT NULL,
  store_id TEXT COLLATE BINARY NOT NULL,
  source_id TEXT COLLATE BINARY NOT NULL,
  realm TEXT COLLATE BINARY NOT NULL CHECK (realm IN ('tenant', 'platform')),
  tenant_id TEXT COLLATE BINARY NOT NULL,
  name TEXT COLLATE BINARY NOT NULL,
  per TEXT COLLATE BINARY NOT NULL,
  value INTEGER NOT NULL CHECK (value > 0),
  PRIMARY KEY (app_id, store_id, source_id, realm, tenant_id, name, per)
);
CREATE TABLE "__mistri_sequence_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_event_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1),
  app_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(app_id) = 'text' AND instr(app_id, char(0)) = 0 AND length(CAST(app_id AS BLOB)) BETWEEN 1 AND 128),
  store_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(store_id) = 'text' AND instr(store_id, char(0)) = 0 AND length(CAST(store_id AS BLOB)) BETWEEN 1 AND 256),
  source_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(source_id) = 'text' AND instr(source_id, char(0)) = 0 AND length(CAST(source_id AS BLOB)) BETWEEN 1 AND 128)
);
CREATE TABLE "__mistri_event_event" (
  event_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(event_id) = 'text' AND instr(event_id, char(0)) = 0 AND length(CAST(event_id AS BLOB)) BETWEEN 1 AND 36) PRIMARY KEY,
  receipt_id TEXT COLLATE BINARY NOT NULL CHECK (typeof(receipt_id) = 'text' AND instr(receipt_id, char(0)) = 0 AND length(CAST(receipt_id AS BLOB)) BETWEEN 1 AND 128) REFERENCES "__mistri_command_receipt" (id) ON DELETE RESTRICT,
  ordinal INTEGER NOT NULL CHECK (typeof(ordinal) = 'integer' AND ordinal BETWEEN 0 AND 31),
  envelope_json TEXT COLLATE BINARY NOT NULL CHECK (typeof(envelope_json) = 'text' AND instr(envelope_json, char(0)) = 0 AND length(CAST(envelope_json AS BLOB)) BETWEEN 1 AND 131072) CHECK (json_valid(envelope_json) AND json_type(envelope_json) = 'object'),
  UNIQUE (receipt_id, ordinal)
);
